/* 2bpp tiles: empty, wall, water, fire, slime, fdoor, wdoor, plat, fireboy, watergirl */
static const uint8_t game_tiles[] = {
    /* 0 empty */
    0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,
