static const uint8_t cell_to_tile[] = {
    TILE_EMPTY, TILE_WALL, TILE_WATER, TILE_FIRE,
    TILE_SLIME, TILE_FDOOR, TILE_WDOOR, TILE_PLAT
};

typedef struct {
    uint8_t x; /* OAM X */
    uint8_t y; /* OAM Y */
    int8_t vy;
    uint8_t grounded;
    uint8_t type;
    uint8_t alive;
    uint8_t on_door;
} hero_t;

static hero_t heroes[2];
static uint8_t active; /* 0 fireboy, 1 watergirl */
static uint8_t game_over;
static uint8_t won;
static uint8_t seeded;
static uint8_t rng_pad_col; /* variable platform column */

static void sound_init(void) {
    NR52_REG = 0x80u;
    NR51_REG = 0xFFu;
    NR50_REG = 0x77u;
}

static void sfx_beep(void) {
    NR10_REG = 0x00u;
    NR11_REG = 0x80u;
    NR12_REG = 0xF1u;
    NR13_REG = 0x83u;
    NR14_REG = 0x87u;
}

static void sfx_boom(void) {
    NR41_REG = 0x00u;
    NR42_REG = 0xF3u;
    NR43_REG = 0x54u;
    NR44_REG = 0x80u;
}

static void sfx_jingle(void) {
    static const uint16_t notes[4] = {1797u, 1849u, 1881u, 1923u};
    uint8_t i;
    uint8_t frame;

    for (i = 0u; i < 4u; ++i) {
        NR21_REG = 0x80u;
        NR22_REG = 0xF2u;
        NR23_REG = (uint8_t)notes[i];
        NR24_REG = (uint8_t)(0x80u | (notes[i] >> 8));
        for (frame = 0u; frame < 8u; ++frame) {
            wait_vbl_done();
        }
    }
}

static uint8_t cell_at(uint8_t tx, uint8_t ty) {
    if (tx >= MAP_W || ty >= MAP_H) {
        return C_WALL;
    }
    return level_map[(uint16_t)ty * MAP_W + tx];
}

static bool is_solid(uint8_t c) {
    return c == C_WALL || c == C_PLAT;
}

/* Pixel bbox vs tiles. OAM (x,y) top-left of sprite is screen (x-8, y-16). */
static bool solid_at_px(uint8_t px, uint8_t py) {
    uint8_t tx = (uint8_t)(px >> 3);
    uint8_t ty = (uint8_t)(py >> 3);
    return is_solid(cell_at(tx, ty));
}

static bool hero_hits_solid(uint8_t hx, uint8_t hy) {
    /* Convert OAM to screen pixel top-left, sample 4 corners inset 1px */
    uint8_t sx = (uint8_t)(hx - 8u);
    uint8_t sy = (uint8_t)(hy - 16u);
    uint8_t x0 = (uint8_t)(sx + 1u);
    uint8_t x1 = (uint8_t)(sx + 6u);
    uint8_t y0 = (uint8_t)(sy + 1u);
    uint8_t y1 = (uint8_t)(sy + 7u);

    return solid_at_px(x0, y0) || solid_at_px(x1, y0) ||
           solid_at_px(x0, y1) || solid_at_px(x1, y1);
}

static uint8_t hazard_under(hero_t *h) {
    uint8_t sx = (uint8_t)(h->x - 8u);
    uint8_t sy = (uint8_t)(h->y - 16u);
    uint8_t cx = (uint8_t)((sx + 3u) >> 3);
    uint8_t cy = (uint8_t)((sy + 6u) >> 3);
    return cell_at(cx, cy);
}

static void paint_level(void) {
    uint8_t x, y;
    uint8_t c;
    uint8_t row[MAP_W];

    for (y = 0u; y < MAP_H; ++y) {
        for (x = 0u; x < MAP_W; ++x) {
            c = level_map[(uint16_t)y * MAP_W + x];
            row[x] = cell_to_tile[c];
        }
        set_bkg_tiles(0u, y, MAP_W, 1u, row);
    }
}

static void build_level(void) {
    uint8_t i;
    uint8_t col;

    for (i = 0u; i < MAP_W * MAP_H; ++i) {
        level_map[i] = level_template[i];
    }

    /* Run-varying floating platform on row 10 */
    col = rng_pad_col;
    if (col < 3u) {
        col = 3u;
    }
    if (col > 14u) {
        col = 14u;
    }
    level_map[(uint16_t)10u * MAP_W + col] = C_PLAT;
    level_map[(uint16_t)10u * MAP_W + (uint8_t)(col + 1u)] = C_PLAT;
    level_map[(uint16_t)10u * MAP_W + (uint8_t)(col + 2u)] = C_PLAT;

    paint_level();
}

static void draw_heroes(void) {
    move_sprite(SPR_FIRE, heroes[0].x, heroes[0].y);
    move_sprite(SPR_WATER, heroes[1].x, heroes[1].y);
}

static void init_heroes(void) {
    /* Start on top ledges: fire left, water right. OAM coords. */
    heroes[0].x = 24u;   /* screen x 16 */
    heroes[0].y = 32u;   /* screen y 16 — row 2 */
    heroes[0].vy = 0;
    heroes[0].grounded = 0u;
    heroes[0].type = TYPE_FIRE;
    heroes[0].alive = 1u;
    heroes[0].on_door = 0u;

    heroes[1].x = 152u;  /* screen x 144 */
    heroes[1].y = 32u;
    heroes[1].vy = 0;
    heroes[1].grounded = 0u;
    heroes[1].type = TYPE_WATER;
    heroes[1].alive = 1u;
    heroes[1].on_door = 0u;

    active = 0u;
    draw_heroes();
}

static void try_seed(uint8_t keys) {
    uint16_t seed;
    if (seeded) {
        return;
    }
    if (keys == 0u) {
        return;
    }
    seed = (uint16_t)DIV_REG;
    seed |= ((uint16_t)DIV_REG << 8);
    if (seed == 0u) {
        seed = 1u;
    }
    initrand(seed);
    rng_pad_col = (uint8_t)(rand() % 12u + 3u);
    seeded = 1u;
    build_level();
    sfx_beep();
}

static void move_hero_x(hero_t *h, int8_t dx) {
    uint8_t nx;
    if (dx == 0) {
        return;
    }
    nx = (uint8_t)((int16_t)h->x + dx);
    /* Keep inside walls roughly */
    if (nx < 16u) {
        nx = 16u;
    }
    if (nx > 160u) {
        nx = 160u;
    }
    if (!hero_hits_solid(nx, h->y)) {
        h->x = nx;
    }
}

static void apply_gravity(hero_t *h) {
    int8_t step;
    uint8_t ny;
    int8_t remaining;

    if (h->vy < MAX_FALL) {
        h->vy = (int8_t)(h->vy + GRAVITY);
        if (h->vy > MAX_FALL) {
            h->vy = MAX_FALL;
        }
    }

    remaining = h->vy;
    h->grounded = 0u;

    if (remaining == 0) {
        /* Still check floor */
        if (hero_hits_solid(h->x, (uint8_t)(h->y + 1u))) {
            h->grounded = 1u;
            h->vy = 0;
        }
        return;
    }

    while (remaining != 0) {
        step = (remaining > 0) ? (int8_t)1 : (int8_t)-1;
        ny = (uint8_t)((int16_t)h->y + step);
        if (hero_hits_solid(h->x, ny)) {
            if (step > 0) {
                h->grounded = 1u;
                h->vy = 0;
            } else {
                h->vy = 0; /* bonk head */
            }
            break;
        }
        h->y = ny;
        remaining = (int8_t)(remaining - step);
    }

    /* Fell off bottom */
    if (h->y > 160u) {
        h->alive = 0u;
    }
}

static void check_hazards(hero_t *h) {
    uint8_t c = hazard_under(h);

    h->on_door = 0u;

    if (c == C_SLIME) {
        h->alive = 0u;
        return;
    }
    if (c == C_WATER && h->type == TYPE_FIRE) {
        h->alive = 0u;
        return;
    }
    if (c == C_FIRE && h->type == TYPE_WATER) {
        h->alive = 0u;
        return;
    }
    if (c == C_FDOOR && h->type == TYPE_FIRE) {
        h->on_door = 1u;
    }
    if (c == C_WDOOR && h->type == TYPE_WATER) {
        h->on_door = 1u;
    }
}

static void update_hero(hero_t *h, uint8_t keys, bool controlled) {
    int8_t dx = 0;

    if (!h->alive) {
        return;
    }

    if (controlled) {
        if (keys & J_LEFT) {
            dx = (int8_t)-MOVE_SPEED;
        } else if (keys & J_RIGHT) {
            dx = (int8_t)MOVE_SPEED;
        }
        if ((keys & J_A) && h->grounded) {
            h->vy = (int8_t)JUMP_V;
            h->grounded = 0u;
            sfx_beep();
        }
    }

    move_hero_x(h, dx);
    apply_gravity(h);
    check_hazards(h);
}

static void initialize_video(void) {
    DISPLAY_OFF;

    SCX_REG = 0u;
    SCY_REG = 0u;
    WY_REG = 0u;
    WX_REG = 7u;
    STAT_REG = 0u;

    BGP_REG = 0xE4u;
    OBP0_REG = 0xE4u;
    OBP1_REG = 0xD0u; /* lighter for watergirl */
    NR52_REG = 0u;

    LCDC_REG = 0x40u;

    set_bkg_data(0x80u, 10u, game_tiles);
    set_sprite_data(0x88u, 2u, &game_tiles[8u * 16u]);

    /* Clear background */
    {
        uint8_t blank[MAP_W];
        uint8_t i, y;
        for (i = 0u; i < MAP_W; ++i) {
            blank[i] = TILE_EMPTY;
        }
        for (y = 0u; y < MAP_H; ++y) {
            set_bkg_tiles(0u, y, MAP_W, 1u, blank);
        }
    }

    set_sprite_tile(SPR_FIRE, TILE_FIREBOY);
    set_sprite_prop(SPR_FIRE, 0u);
    set_sprite_tile(SPR_WATER, TILE_WATERGIRL);
    set_sprite_prop(SPR_WATER, S_PALETTE);

    SPRITES_8x8;
    SHOW_BKG;
    SHOW_SPRITES;
    DISPLAY_ON;
}

static void initialize_game(void) {
    uint8_t i;

    seeded = 0u;
    game_over = 0u;
    won = 0u;
    rng_pad_col = 8u; /* default until first input reseeds layout */

    for (i = 0u; i < MAP_W * MAP_H; ++i) {
        level_map[i] = level_template[i];
    }
    /* default pad */
    level_map[(uint16_t)10u * MAP_W + 8u] = C_PLAT;
    level_map[(uint16_t)10u * MAP_W + 9u] = C_PLAT;
    level_map[(uint16_t)10u * MAP_W + 10u] = C_PLAT;
    paint_level();
    init_heroes();
}

void main(void) {
    uint8_t keys;
    uint8_t prev_keys = 0u;

    wait_vbl_done();

    initialize_video();
    sound_init();
    initialize_game();
    NOVA_STATE = 1u;

    while (!game_over) {
        keys = joypad();
        try_seed(keys);

        /* B edge: switch active hero */
        if ((keys & J_B) && !(prev_keys & J_B)) {
            active ^= 1u;
            sfx_beep();
        }

        update_hero(&heroes[0], keys, active == 0u);
        update_hero(&heroes[1], keys, active == 1u);
        draw_heroes();

        if (!heroes[0].alive || !heroes[1].alive) {
            game_over = 1u;
            won = 0u;
        } else if (heroes[0].on_door && heroes[1].on_door) {
            game_over = 1u;
            won = 1u;
        }

        prev_keys = keys;
        wait_vbl_done();
    }

    NOVA_STATE = won ? 2u : 3u;
    if (won) {
        sfx_jingle();
    } else {
        sfx_boom();
    }
    while (true) {
        wait_vbl_done();
    }
}

