    0xFF,0xFF,0x81,0x81,0xBD,0xBD,0xA5,0xA5,0xA5,0xA5,0x81,0x81,0x81,0x81,0xFF,0xFF,
    /* 6 water door */
    0xFF,0x00,0x81,0x7E,0x99,0x66,0x81,0x7E,0x99,0x66,0x81,0x7E,0x81,0x7E,0xFF,0x00,
    /* 7 thin platform */
