    /* 8 fireboy */
    0x3C,0x3C,0x7E,0x5A,0x7E,0x7E,0x3C,0x3C,0x18,0x18,0x3C,0x24,0x24,0x24,0x66,0x66,
    /* 9 watergirl */
    0x18,0x18,0x3C,0x3C,0x7E,0x5A,0x7E,0x7E,0x3C,0x3C,0x18,0x18,0x2C,0x2C,0x6E,0x6E
};

