        if ((keys & J_A) && h->grounded) {
            h->vy = (int8_t)JUMP_V;
            h->grounded = 0u;
            sfx_beep();
        }
    }

    move_hero_x(h, dx);
    apply_gravity(h);
    check_hazards(h);
}

